/**
 * Bounded-concurrency task pooling shared by the graph walk and export, the
 * process-wide request gate the HTTP client holds every data request in, and
 * the single-flight read cache built on {@link SharedOperation}.
 * @module dsh-zotero/concurrency
 */

import { HarnessError } from '@deepseek-ai/dsh-error'
import { TOOL_ABORTED } from '@deepseek-ai/dsh-tools'
import { TOOL_ABORTED_MESSAGE } from './abort.js'

/**
 * Map `items` through `worker` with at most `concurrency` calls in flight,
 * preserving the input order in the results.
 *
 * Failure is fail-fast and fail-closed: the first worker rejection aborts the
 * pool's signal (so cooperative in-flight workers can cancel their I/O), stops
 * further items from starting, and rethrows that rejection. `options.signal`
 * links caller cancellation into the same pool signal.
 */
export async function mapWithConcurrency<T, R>(
  items: readonly T[],
  concurrency: number,
  worker: (item: T, signal: AbortSignal) => Promise<R>,
  options?: { signal?: AbortSignal },
): Promise<R[]> {
  if (!Number.isInteger(concurrency) || concurrency <= 0) {
    throw new Error(
      `mapWithConcurrency requires a positive integer concurrency, got ${concurrency}`,
    )
  }
  const pool = new AbortController()
  const outer = options?.signal
  const onOuterAbort = (): void => {
    pool.abort(outer?.reason)
  }
  if (outer !== undefined) {
    if (outer.aborted) onOuterAbort()
    else outer.addEventListener('abort', onOuterAbort, { once: true })
  }
  const results = new Array<R>(items.length)
  let next = 0
  let failed = false
  let firstError: unknown = undefined
  const run = async (): Promise<void> => {
    for (;;) {
      if (failed || pool.signal.aborted) return
      const index = next
      next += 1
      if (index >= items.length) return
      try {
        results[index] = await worker(items[index]!, pool.signal)
      } catch (error) {
        if (!failed) {
          failed = true
          firstError = error
          pool.abort(error)
        }
        throw error
      }
    }
  }
  try {
    const tasks = Array.from({ length: Math.min(concurrency, items.length) }, () => run())
    await Promise.allSettled(tasks)
    if (firstError !== undefined) {
      throw firstError
    }
    if (outer?.aborted === true) {
      throw new HarnessError(TOOL_ABORTED_MESSAGE, TOOL_ABORTED, { cause: outer.reason })
    }
    return results
  } finally {
    outer?.removeEventListener('abort', onOuterAbort)
  }
}

/**
 * An in-flight deduplicated operation shared across concurrent waiters.
 * Tracks waiter count and aborts the underlying controller only when all
 * waiters have detached before settlement.
 */
export interface SharedOperation<T> {
  readonly controller: AbortController
  promise: Promise<T>
  waiters: number
  settled: boolean
}

/**
 * Await a shared in-flight operation without letting one cancelled waiter abort
 * other live waiters. The underlying request is aborted only when the last waiter
 * detaches.
 */
export async function awaitSharedOperation<T>(
  operation: SharedOperation<T>,
  signal: AbortSignal | undefined,
): Promise<T> {
  if (signal?.aborted) throw new HarnessError(TOOL_ABORTED_MESSAGE, TOOL_ABORTED)
  operation.waiters += 1
  let released = false
  const release = (): void => {
    if (released) return
    released = true
    operation.waiters -= 1
    if (operation.waiters === 0 && !operation.settled) operation.controller.abort()
  }
  if (signal === undefined) {
    try {
      return await operation.promise
    } finally {
      release()
    }
  }

  let rejectAborted!: (reason?: unknown) => void
  const aborted = new Promise<never>((_, reject) => {
    rejectAborted = reject
  })
  const onAbort = (): void => {
    release()
    rejectAborted(new HarnessError(TOOL_ABORTED_MESSAGE, TOOL_ABORTED))
  }
  signal.addEventListener('abort', onAbort, { once: true })
  if (signal.aborted) onAbort()
  try {
    return await Promise.race([operation.promise, aborted])
  } finally {
    signal.removeEventListener('abort', onAbort)
    release()
  }
}

/**
 * How one {@link sharedRead} entry is looked up and stored: the key concurrent
 * callers share one in-flight load under, the cache hit test for the current
 * caller, and the cache keys one successful load is stored under.
 */
interface SharedReadKeys<T> {
  /** Key under which concurrent callers share one in-flight load. */
  readonly flightKey: string
  /** A cache hit for the current caller, or undefined on a miss. */
  readonly find: () => T | undefined
  /** The cache keys one successful load is stored under (all aliases it must answer). */
  readonly store: (value: T) => readonly string[]
}

/** The cache surface {@link sharedRead} needs; `Map` and the bounded caches both satisfy it. */
interface SharedReadCache<T> {
  get(key: string): T | undefined
  set(key: string, value: T): void
}

/**
 * Read one value through a cache with at most one in-flight load per flight
 * key. A cache hit returns immediately; concurrent misses share the load; the
 * successful value is stored under every alias {@link SharedReadKeys.store}
 * names; a load that fails or is aborted is never cached. Waiters share the
 * operation through {@link awaitSharedOperation}, so one cancelled caller does
 * not abort the read for the others.
 *
 * A settled or aborted operation is never reused. An operation whose last
 * waiter cancelled has its controller aborted while its promise may still be
 * pending, and joining that doomed operation would hand a fresh caller the
 * cancellation error it did not cause; the next read therefore starts a new
 * load instead.
 * @param input - the caches, key family, loader, and caller cancellation.
 * @returns the cached or freshly loaded value.
 */
export async function sharedRead<T>(input: {
  readonly cache: SharedReadCache<T>
  readonly inFlight: Map<string, SharedOperation<T>>
  readonly keys: SharedReadKeys<T>
  readonly load: (signal: AbortSignal) => Promise<T>
  readonly signal?: AbortSignal
}): Promise<T> {
  if (input.signal?.aborted) throw new HarnessError(TOOL_ABORTED_MESSAGE, TOOL_ABORTED)
  const { cache, inFlight, keys } = input
  const cached = keys.find()
  if (cached !== undefined) return cached

  let operation = inFlight.get(keys.flightKey)
  if (operation === undefined || operation.settled || operation.controller.signal.aborted) {
    const controller = new AbortController()
    // The operation is assigned synchronously below, before any microtask can
    // run the loader's cleanup; the guard keeps that ordering honest.
    let created: SharedOperation<T> | undefined
    const promise = (async () => {
      const value = await input.load(controller.signal)
      for (const key of keys.store(value)) cache.set(key, value)
      return value
    })().finally(() => {
      if (created === undefined) return
      created.settled = true
      if (inFlight.get(keys.flightKey) === created) inFlight.delete(keys.flightKey)
    })
    created = { controller, promise, waiters: 0, settled: false }
    // A sole cancelled waiter leaves nobody to consume the shared rejection.
    // Keep it observed without changing the promise returned to real waiters.
    void promise.catch(() => undefined)
    inFlight.set(keys.flightKey, created)
    operation = created
  }
  return await awaitSharedOperation(operation, input.signal)
}

/** Thrown when a queued holder is aborted before it ever takes its slot. */
export class GateAbortedError extends Error {
  constructor() {
    super('aborted while waiting for a slot')
    this.name = 'GateAbortedError'
  }
}

interface GateWaiter {
  readonly take: () => void
  readonly giveUp: (error: unknown) => void
  readonly signal: AbortSignal | undefined
  readonly onAbort: (() => void) | undefined
}

/**
 * A counted gate: at most `limit` holders at a time, everyone else queues in
 * arrival order.
 *
 * Each pool bounds its own fan-out, but pools multiply, since several
 * concurrent tool calls each start one. The client that every request flows
 * through therefore holds one gate as well, and the load on Zotero is bounded
 * by that number rather than by how many calls happen to run at once.
 *
 * The queue is abortable in both directions: a holder whose signal is already
 * aborted never takes a slot, and a queued one leaves the queue on abort
 * without consuming a slot nobody is going to use. An aborted waiter rejects
 * with {@link GateAbortedError}; the caller translates that into its own
 * cancellation error, because only the caller knows what "aborted" means for
 * its layer.
 */
export class ConcurrencyGate {
  private active = 0
  private readonly waiting: GateWaiter[] = []

  constructor(private limit: number) {
    if (!Number.isInteger(limit) || limit <= 0) {
      throw new Error(`ConcurrencyGate requires a positive integer limit, got ${limit}`)
    }
  }

  /** Existing holders drain after a shrink; newly available slots admit queued work in order. */
  setLimit(limit: number): void {
    if (!Number.isInteger(limit) || limit <= 0)
      throw new Error(`ConcurrencyGate requires a positive integer limit, got ${limit}`)
    this.limit = limit
    this.admitQueued()
  }

  private admitQueued(): void {
    while (this.active < this.limit) {
      const next = this.waiting.shift()
      if (next === undefined) return
      this.active++
      next.take()
    }
  }

  /**
   * Take a slot.
   * @param signal - the caller's cancellation; aborting it while queued
   *   rejects instead of waiting for a slot.
   * @returns the release function; calling it more than once is a no-op, so
   *   a `finally` release cannot hand out a second slot.
   */
  async acquire(signal?: AbortSignal): Promise<() => void> {
    if (signal?.aborted) throw new GateAbortedError()
    if (this.active < this.limit) {
      this.active += 1
      return this.releaseOf()
    }
    return await new Promise<() => void>((resolve, reject) => {
      const waiter: GateWaiter = {
        take: () => {
          this.detach(waiter)
          resolve(this.releaseOf())
        },
        giveUp: (error) => {
          this.detach(waiter)
          reject(error)
        },
        signal,
        onAbort:
          signal === undefined
            ? undefined
            : () => {
                waiter.giveUp(new GateAbortedError())
              },
      }
      this.waiting.push(waiter)
      if (waiter.onAbort !== undefined) {
        waiter.signal?.addEventListener('abort', waiter.onAbort, { once: true })
        // The signal may have aborted between the check above and this
        // listener, and an aborted signal never replays its event, so a waiter
        // left queued that way would wait for a slot it no longer wants.
        if (waiter.signal?.aborted === true) waiter.giveUp(new GateAbortedError())
      }
    })
  }

  /** Stop listening for a waiter's abort; safe to call for a waiter that never listened. */
  private detach(waiter: GateWaiter): void {
    const index = this.waiting.indexOf(waiter)
    if (index >= 0) this.waiting.splice(index, 1)
    if (waiter.onAbort !== undefined) waiter.signal?.removeEventListener('abort', waiter.onAbort)
  }

  /** The idempotent release handed to one holder. */
  private releaseOf(): () => void {
    let released = false
    return () => {
      if (released) return
      released = true
      this.active -= 1
      this.admitQueued()
    }
  }
}

/**
 * Take one gate slot, translating a queued abort into the same cancellation
 * error a request aborted mid-flight produces. The caller cancelled, and how
 * far the request had got is not part of the contract. `acquire` rejects
 * in exactly one case (a queued holder whose signal was aborted), so the
 * rejection is reported as that cancellation and carried along as its cause:
 * a gate that ever failed for another reason stays visible there rather than
 * being silently reclassified.
 * @param gate - the gate to take the slot from.
 * @param signal - the caller's cancellation.
 * @returns the release function.
 */
export async function acquireSlot(
  gate: ConcurrencyGate,
  signal: AbortSignal | undefined,
): Promise<() => void> {
  try {
    return await gate.acquire(signal)
  } catch (error) {
    throw new HarnessError(TOOL_ABORTED_MESSAGE, TOOL_ABORTED, { cause: error })
  }
}
